task.vi:
Giả sử statement2 gây ra ngoại lệ trong khối try-catch sau:

try
{
  statement1;
  statement2;
  statement3;
}
catch (Exception1& ex1)
{
}
catch (Exception2& ex2)
{
}

statement4;

Trả lời các câu hỏi sau:
(a) statement3 có được thực thi không?
(b) Nếu ngoại lệ không được bắt, statement4 có được thực thi không?
(c) Nếu ngoại lệ được bắt trong một khối catch, statement4 có được thực thi không?

task.en:
Suppose that statement2 causes an exception in the following try-catch block:

try
{
  statement1;
  statement2;
  statement3;
}
catch (Exception1& ex1)
{
}
catch (Exception2& ex2)
{
}

statement4;

Answer the following questions:
(a) Will statement3 be executed?
(b) If the exception is not caught, will statement4 be executed?
(c) If the exception is caught in the catch block, will statement4 be executed?

example.code:
#include <iostream>
#include <string>
#include <stdexcept>

class NonPositiveSideException : public std::logic_error {
private:
    double side;
public:
    explicit NonPositiveSideException(double s)
        : std::logic_error("Non-positive side"), side(s) {}
    double getSide() const { return side; }
};

class TriangleException : public std::logic_error {
private:
    double side1, side2, side3;
public:
    TriangleException(double s1, double s2, double s3)
        : std::logic_error("Invalid triangle"), side1(s1), side2(s2), side3(s3) {}
    double getSide1() const { return side1; }
    double getSide2() const { return side2; }
    double getSide3() const { return side3; }
};

class Triangle {
private:
    double side1, side2, side3;

    static void checkPositive(double s) {
        if (s <= 0.0) {
            throw NonPositiveSideException(s);
        }
    }

    static bool isValid(double a, double b, double c) {
        return (a + b > c) && (a + c > b) && (b + c > a);
    }

public:
    Triangle(double s1, double s2, double s3) {
        checkPositive(s1);
        checkPositive(s2);
        checkPositive(s3);
        if (!isValid(s1, s2, s3)) {
            throw TriangleException(s1, s2, s3);
        }
        side1 = s1;
        side2 = s2;
        side3 = s3;
    }

    double getPerimeter() const { return side1 + side2 + side3; }
};

void testTriangle(double a, double b, double c) {
    try {
        std::cout << "Testing sides: " << a << " " << b << " " << c << std::endl;
        Triangle t(a, b, c);
        std::cout << "Valid triangle created. Perimeter: " << t.getPerimeter() << std::endl;
    }
    catch (const NonPositiveSideException& ex) {
        std::cout << "[Caught NonPositiveSideException] " << ex.what() 
                  << " with value " << ex.getSide() << std::endl;
    }
    catch (const TriangleException& ex) {
        std::cout << "[Caught TriangleException] " << ex.what() 
                  << ": sides " << ex.getSide1() << ", " << ex.getSide2() 
                  << ", " << ex.getSide3() << std::endl;
    }
    catch (const std::logic_error& ex) {
        std::cout << "[Caught generic logic_error] " << ex.what() << std::endl;
    }
    catch (...) {
        std::cout << "[Caught unknown exception]" << std::endl;
    }
}

int main() {
    testTriangle(3.0, 4.0, 5.0);
    testTriangle(-1.0, 4.0, 5.0);
    testTriangle(1.0, 2.0, 1.0);
    return 0;
}
